        "api_calls": [
            {
                "call_id": "c1",
                "api": "robot.pick",
                "args": {
                    "item": "sample_tube",
                    "from_location": "fridge"
                },
                "source_step_id": "s1"
            },
            {
                "call_id": "c2",
                "api": "heater.place",
                "args": {
                    "item": "sample_tube"
                },
                "source_step_id": "s1"
            },
            {
                "call_id": "c3",
