                "args": {
                    "minutes": 10
                },
                "source_step_id": "s1"
            },
            {
                "call_id": "c5",
                "api": "heater.remove",
                "args": {
                    "item": "sample_tube"
                },
                "source_step_id": "s1"
            },
            {
                "call_id": "c6",
                "api": "robot.place",
                "args": {
                    "item": "sample_tube",
                    "to_location": "fridge"
                },
                "source_step_id": "s1"
            }
        ]
    },
    "contains_unregistered_api": false,
